const baseValue = msg.payload;
let resultsArray = [];

for (let i = 1; i <= 3; i++) {
    resultsArray.push(baseValue * i);
}

let statusText = baseValue > 5 ? "Значение больше 5" : "Значение 5 или меньше";

msg.payload = {
    student: "Лисай",
    originalValue: baseValue,
    calculatedArray: resultsArray,
    status: statusText,
    timestamp: new Date().toISOString()
};

return msg;
